--
-- Table structure for table `services`
--

DROP TABLE IF EXISTS `services`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `services` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `category_id` int(11) DEFAULT NULL,
  `title` varchar(255) NOT NULL,
  `details` text NOT NULL,
  `pricing` decimal(12,2) NOT NULL,
  `delivery_start_date` date DEFAULT NULL,
  `delivery_end_date` date DEFAULT NULL,
  `attributes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`attributes`)),
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL,
  `use_delivery_date` tinyint(1) DEFAULT 0,
  `duration_days` int(11) DEFAULT NULL,
  `currency` varchar(10) NOT NULL DEFAULT 'BDT',
  `gallery` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`gallery`)),
  `price_type` enum('ONE_TIME','RENEWAL') NOT NULL DEFAULT 'ONE_TIME',
  `renewal_interval` enum('MONTHLY','SIX_MONTH','YEARLY') DEFAULT NULL,
  `short_description` text DEFAULT NULL,
  `thumbnail_type` enum('IMAGE','YOUTUBE','LOCAL_VIDEO') NOT NULL DEFAULT 'IMAGE',
  `thumbnail_url` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `services_category_id_idx` (`category_id`),
  KEY `services_company_id_idx` (`company_id`),
  KEY `services_is_active_idx` (`is_active`),
  CONSTRAINT `services_category_id_fkey` FOREIGN KEY (`category_id`) REFERENCES `service_categories` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `services_company_id_fkey` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

